char* get_random_sample(char *next_item) {
    static char *R = NULL;
    static long N = 0; // Item counter

    N++;

    if (N == 1) {
        if (R) free(R);
        R = strdup(next_item); // Initialize reservoir
        return R;
    }

    // Probability of replacement is 1/N
    // Assumes rand() is appropriately seeded
    if ((rand() % N) == 0) {
        if (R) free(R);
        R = strdup(next_item); // Replace R
    }

    return R;
}
// Note: Final R must be freed by the caller.
// Requires <stdlib.h>, <string.h> (for strdup)
// Stream items must be passed sequentially.
